	benchmarks := getBenchmarkSiteTestCases()
	for _, bm := range benchmarks {
		if bm.name != "Deep content tree" {
			continue
		}
		b.Run(bm.name, func(b *testing.T) {
			s := bm.create(b)

			err := s.BuildE(BuildCfg{})
			if err != nil {
				b.Fatal(err)
